import sys
from playwright.sync_api import sync_playwright
SS=open('/home/claude/work/tests-front/stub_support.js',encoding='utf8').read()
SP=open('/home/claude/work/tests-front/stub_projects.js',encoding='utf8').read()
res=[]
def check(n,c): res.append(bool(c)); print(('PASS ' if c else 'FAIL ')+n)
with sync_playwright() as p:
    b=p.chromium.launch(); errs=[]
    def new(url,stub,pre="",w=1200,post=""):
        pg=b.new_page(viewport={'width':w,'height':1000},locale='fr-FR'); pg.on("pageerror",lambda e:errs.append(str(e)))
        pg.on("dialog",lambda d:d.accept()); pg.route("**/cdn.jsdelivr.net/**",lambda r:r.abort()); pg.add_init_script(pre+stub+post); pg.goto("http://localhost:8765/"+url); pg.wait_for_timeout(1000); return pg
    # ---------- support membre
    s=new("support.html",SS)
    check("support : mes demandes (2), pas celles des autres", s.locator("#t-list .ocard").count()==2 and "Question sur l'IA" not in s.inner_text("#t-list"))
    s.click('[data-open="t1"]'); s.wait_for_timeout(400)
    check("fil : description et réponse du support, HTML échappé", "Dépôt non crédité" in s.inner_text("#th-title") and "vérifions" in s.inner_text("#th-msgs") and s.locator("#th-desc b, #th-msgs i").count()==0)
    check("fil : note interne invisible du membre", "Flutterwave" not in s.inner_text("#th-msgs"))
    check("fil : statut « en attente de votre réponse »", "attente" in s.inner_text("#th-status"))
    s.fill("#th-body","Référence du dépôt : DEP-1234"); s.click("#th-go"); s.wait_for_timeout(500)
    check("réponse du membre envoyée, ticket rouvert", s.evaluate("window.__db.support_messages.some(m=>m.body.includes('DEP-1234')&&m.sender_id==='u1')") and s.evaluate("window.__db.support_tickets[0].status")=="open")
    s.fill("#t-sub","ab"); s.fill("#t-desc","court"); s.click("#t-go"); s.wait_for_timeout(200)
    check("création : objet/description trop courts refusés sans appel", "3 à 120" in s.inner_text("#t-err") and s.evaluate("window.__db.support_tickets.length")==3)
    s.fill("#t-sub","Problème de connexion"); s.fill("#t-desc","Je n'arrive plus à me connecter depuis hier soir."); s.select_option("#t-cat","account"); s.click("#t-go"); s.wait_for_timeout(600)
    check("création : ticket créé, référence affichée, fil ouvert", s.evaluate("window.__db.support_tickets.some(t=>t.subject==='Problème de connexion'&&t.category==='account')") and "Référence" in s.inner_text("#t-ok") and "Problème de connexion" in s.inner_text("#th-title"))
    s.click("#th-close"); s.wait_for_timeout(500)
    check("clôture : statut clos, formulaire de réponse masqué", s.evaluate("window.__db.support_tickets.find(t=>t.subject==='Problème de connexion').status")=="closed" and s.is_hidden("#th-form"))
    f=new("support.html",SS,"",1200,"window.__fail='too_many_open_tickets';")
    f.fill("#t-sub","Un sujet valide"); f.fill("#t-desc","Une description suffisamment longue pour passer."); f.click("#t-go"); f.wait_for_timeout(400)
    check("plafond de demandes ouvertes : message clair", "5 demandes" in f.inner_text("#t-err"))
    h=new("support.html#t1",SS); check("lien de notification (#id) ouvre la demande", "Dépôt non crédité" in h.inner_text("#th-title"))
    # ---------- support admin
    n=new("admin-support.html",SS)
    check("admin-support : non-personnel refusé", "refusé" in n.inner_text("#state").lower() and n.is_hidden("#panel"))
    a=new("admin-support.html",SS,"window.__STAFF=true;")
    check("admin-support : tous les tickets (3)", a.locator("#t-adm tbody tr").count()==3)
    a.click('[data-f="open"]'); a.wait_for_timeout(300)
    check("filtre « ouvertes »", a.locator("#t-adm tbody tr").count()==1 and "Question sur l'IA" in a.inner_text("#t-adm"))
    a.click('[data-open="t2"]'); a.wait_for_timeout(300)
    a.fill("#d-body","Lia utilise plusieurs modèles."); a.click('#d-form button[type=submit]'); a.wait_for_timeout(500)
    check("réponse publique : ticket passe en attente du membre", a.evaluate("window.__db.support_tickets.find(t=>t.id==='t2').status")=="waiting_user")
    a.click('[data-f=""]'); a.wait_for_timeout(300); a.click('[data-open="t2"]'); a.wait_for_timeout(300)
    a.fill("#d-body","Cliente fidèle, traiter vite"); a.check("#d-int"); a.click('#d-form button[type=submit]'); a.wait_for_timeout(500)
    check("note interne ajoutée et marquée", a.evaluate("window.__db.support_messages.some(m=>m.body.includes('fidèle')&&m.is_internal)") and "Note interne" in a.inner_text("#d-msgs"))
    a.select_option("#d-pr","high"); a.select_option("#d-st","in_progress"); a.click("#d-save"); a.wait_for_timeout(500)
    check("priorité et statut enregistrés", a.evaluate("window.__db.support_tickets.find(t=>t.id==='t2').priority")=="high" and a.evaluate("window.__db.support_tickets.find(t=>t.id==='t2').status")=="in_progress")
    a.click("#d-assign"); a.wait_for_timeout(300)
    check("attribution à soi", a.evaluate("window.__db.support_tickets.find(t=>t.id==='t2').assigned_to")=="u1")
    # ---------- terminal
    t=new("terminal.html",SP)
    def cmd(c,w=300):
        t.fill("#tm-in",c); t.press("#tm-in","Enter"); t.wait_for_timeout(w); return t.inner_text("#tm-out")
    check("terminal : message d'accueil", "Terminal de projet" in t.inner_text("#tm-out"))
    o=cmd("projects"); check("projects : mes projets et le public d'un autre", "mon-site" in o and "public-autre" in o)
    o=cmd("ls"); check("ls sans projet : erreur explicite", "Aucun projet sélectionné" in o)
    cmd("use mon-site"); check("use : prompt mis à jour", "aldetic:mon-site$" in t.inner_text("#tm-prompt"))
    o=cmd("ls"); check("ls : fichiers avec version", "index.html" in o and "app.js" in o and "v2" in o)
    o=cmd("cat app.js"); check("cat : contenu du fichier", "const a = 1;" in o and 'return "x"' in o)
    o=cmd("cat inexistant.txt"); check("cat : fichier absent", "Fichier introuvable" in o)
    o=cmd("head app.js 1"); check("head : première ligne seulement", o.count("function f()")==1 and o.split("head app.js 1")[-1].count("function")==0)
    o=cmd("wc app.js"); check("wc : lignes, mots, caractères", "app.js" in o.split("wc app.js")[-1])
    o=cmd("grep salut"); check("grep : recherche insensible à la casse, numéro de ligne", "index.html:1:" in o)
    o=cmd("grep zzzintrouvable"); check("grep : aucun résultat", "Aucun résultat" in o)
    o=cmd("versions index.html"); check("versions : historique", "v2" in o.split("versions index.html")[-1] and "v1" in o.split("versions index.html")[-1])
    o=cmd("stats"); check("stats : fichiers et versions", "Fichiers : 2" in o)
    o=cmd("rm -rf /"); check("commande dangereuse/inconnue : refusée, rien d'exécuté", "Commande inconnue" in o and t.evaluate("window.__db.project_files.length")==4)
    o=cmd("constructor"); check("noms hérités (constructor) : refusés", o.count("Commande inconnue")>=2)
    cmd("use public-autre"); o=cmd("cat README.md"); check("projet public d'un autre : lecture seule autorisée", "# public" in o)
    o=cmd("versions README.md"); check("historique d'un projet d'autrui : lecture refusée ou vide, aucune fuite", "# public" not in o.split("versions README.md")[-1])
    t.focus("#tm-in"); t.keyboard.press("ArrowUp"); check("historique : flèche haut rappelle la dernière commande", t.input_value("#tm-in")=="versions README.md")
    cmd("clear"); check("clear : écran vidé", t.locator(".tm-line").count()==0)
    check("terminal : pas de défilement horizontal mobile", new("terminal.html",SP,"",390).evaluate("document.documentElement.scrollWidth<=window.innerWidth+1"))
    print("ERREURS:",sorted(set(errs)))
    check("aucune erreur JS propre (hors CDN)", not [x for x in errs if 'gsap' not in x.lower() and 'ScrollTrigger' not in x])
    b.close()
print(f"{sum(res)}/{len(res)} OK"); sys.exit(0 if all(res) else 1)
